 "A 1% gap (0.01) typically cuts solve time dramatically with negligible impact on results. Only relevant for MILP models with integer variables.": "Eine Lücke von 1 % (0,01) verkürzt die Lösungszeit meist deutlich bei vernachlässigbarem Einfluss auf die Ergebnisse. Nur für MILP-Modelle mit ganzzahligen Variablen relevant.",
 "A 1-day window with 6-hour resolution and feasibility slack. Run this first whenever you change the model structure.": "Ein 1-Tages-Fenster mit 6-Stunden-Auflösung und Machbarkeitsspielraum. Führen Sie dies immer zuerst aus, wenn Sie die Modellstruktur ändern.",
 "A 3-hour resolution is the most common choice in academic and commercial energy system studies.": "Eine 3-Stunden-Auflösung ist die häufigste Wahl in wissenschaftlichen und kommerziellen Energiesystemstudien.",
