 "A node of your energy system: a city, region, power plant or substation. Technologies are assigned to locations.": "Ein Knoten Ihres Energiesystems: eine Stadt, Region, ein Kraftwerk oder Umspannwerk. Technologien werden Standorten zugeordnet.",
