 "A single week is sufficient to analyse short-run operational dispatch. Adjust dates to a peak-solar week in your region.": "Eine einzelne Woche genügt, um den kurzfristigen Kraftwerkseinsatz zu analysieren. Passen Sie die Daten an eine Woche mit hoher Solareinspeisung in Ihrer Region an.",
