 "Click": "Klicken",
 "Click \"Add Location\" in the left panel, then click the map to drop nodes — city demand centers, substations, power plants.": "Klicken Sie im linken Bereich auf „Standort hinzufügen“ und dann auf die Karte, um Knoten zu setzen — städtische Lastzentren, Umspannwerke, Kraftwerke.",
 "Click \"Download & Import\"": "Auf „Herunterladen & importieren“ klicken",
 "Click \"Generate Mesh Network\" to build a graph of intersections from the visible power line layer. Import the result as model Locations & Links with one click.": "Klicken Sie auf „Maschennetz erzeugen“, um aus der sichtbaren Stromleitungsebene einen Graphen der Kreuzungen zu bilden. Importieren Sie das Ergebnis mit einem Klick als Standorte & Verbindungen des Modells.",
 "Click \"Generate Mesh Network\" — nodes appear at intersections.": "Auf „Maschennetz erzeugen“ klicken — Knoten erscheinen an Kreuzungen.",
 "Click \"Import as Locations & Links\" → model is populated.": "Auf „Als Standorte & Verbindungen importieren“ klicken → das Modell wird befüllt.",
 "Click a config card to configure it. Nest it in a Year to scope it to that year, or leave it on the canvas for all years.": "Klicken Sie auf eine Konfigurationskarte, um sie einzurichten. Legen Sie sie in ein Jahr, um sie auf dieses Jahr zu beschränken, oder lassen Sie sie für alle Jahre auf der Arbeitsfläche.",
 "Click a first location, then a second.": "Klicken Sie auf einen ersten Standort, dann auf einen zweiten.",
