 "Estimated CAPEX by Technology": "Geschätzter CAPEX nach Technologie",
 "Evening-heavy (g2)": "Abendlastig (g2)",
 "Evenly": "Gleichmäßig",
 "Every TEMPO model shares the same internal structure regardless of which engine you run it on — Calliope 0.6.8, Calliope 0.7, PyPSA, OSeMOSYS, or AdOpT-NET0. The engine-specific translation happens automatically at run time.": "Jedes TEMPO-Modell hat dieselbe interne Struktur, unabhängig von der Engine — Calliope 0.6.8, Calliope 0.7, PyPSA, OSeMOSYS oder AdOpT-NET0. Die engine-spezifische Übersetzung erfolgt automatisch zur Laufzeit.",
 "Every location coloured by its main technology and sized by capacity. Click a marker for details.": "Jeder Standort ist nach seiner Haupttechnologie eingefärbt und nach Kapazität skaliert. Für Details eine Markierung anklicken.",
 "Every location you place appears here. Select one to zoom to it, edit it, or clear the list.": "Jeder gesetzte Standort erscheint hier. Wählen Sie einen aus, um dorthin zu zoomen, ihn zu bearbeiten oder die Liste zu leeren.",
 "Every page in the left sidebar, grouped by what you'll use it for.": "Alle Seiten der linken Seitenleiste, gruppiert nach ihrem Zweck.",
 "Every technology belongs to a parent type that defines its fundamental behaviour. These map to Calliope 0.6.8 and 0.7 — the PyPSA, OSeMOSYS and AdOpT-NET0 translators derive equivalent concepts automatically.": "Jede Technologie gehört zu einem Elterntyp, der ihr grundlegendes Verhalten festlegt. Diese entsprechen Calliope 0.6.8 und 0.7 — die Übersetzer für PyPSA, OSeMOSYS und AdOpT-NET0 leiten gleichwertige Konzepte automatisch ab.",
 "Every year becomes one run. Parallel solves them all at once; Sequential solves them one after another.": "Jedes Jahr wird ein Lauf. „Parallel“ löst alle gleichzeitig; „Sequenziell“ löst sie nacheinander.",
 "Everything is stored on this device. Clear all data here if needed.": "Alles wird auf diesem Gerät gespeichert. Hier können Sie bei Bedarf alle Daten löschen.",
