 "Open Creation. In the right sidebar choose a continent → country → region. The map zooms to your area and loads real power infrastructure.": "„Erstellen“ öffnen. In der rechten Seitenleiste Kontinent → Land → Region wählen. Die Karte zoomt auf Ihr Gebiet und lädt die reale Strominfrastruktur.",
 "Open Energy Ontology": "Open Energy Ontology",
 "Open Model Advisor settings": "Einstellungen des Modellberaters öffnen",
 "Open Source Energy Modelling System": "Open Source Energy Modelling System",
 "Open Source Energy Modelling System (via otoole + GLPK), in its own isolated Python environment. Hourly time series are aggregated into configurable timeslices at run time. Also enables OSeMOSYS dataset import/export. Requires Python 3.10+; the GLPK solver is bundled on Windows.": "Open Source Energy Modelling System (über otoole + GLPK) in einer eigenen, isolierten Python-Umgebung. Stündliche Zeitreihen werden zur Laufzeit zu konfigurierbaren Zeitscheiben aggregiert. Ermöglicht auch Import/Export von OSeMOSYS-Datensätzen. Erfordert Python 3.10+; der GLPK-Solver ist unter Windows enthalten.",
 "Open Source Energy Modelling System — otoole-compatible CSV dataset": "Open Source Energy Modelling System — otoole-kompatibler CSV-Datensatz",
 "Open results, read logs, download JSON or delete old runs.": "Ergebnisse öffnen, Protokolle lesen, JSON herunterladen oder alte Läufe löschen.",
 "Open this any time for a short explanation of locations, links and polylines.": "Öffnen Sie dies jederzeit für eine kurze Erklärung zu Standorten, Verbindungen und Polylinien.",
 "Open this panel to search a country or region and load the real transmission grid, power plants and substations as a reference while you draw.": "Öffnen Sie diesen Bereich, um ein Land oder eine Region zu suchen und beim Zeichnen das reale Übertragungsnetz, Kraftwerke und Umspannwerke als Referenz zu laden.",
 "Open-source LP/MIP solver — recommended free option.": "Open-Source-LP/MIP-Solver — empfohlene kostenlose Option.",
 "OpenAI-compatible": "OpenAI-kompatibel",
 "OpenStreetMap is busy or the area is too large. Try a smaller region or raise the min-voltage, then reselect.": "OpenStreetMap ist ausgelastet oder das Gebiet zu groß. Wählen Sie eine kleinere Region oder erhöhen Sie die Mindestspannung und wählen Sie erneut.",
 "OpenTech·DB offline — catalog unavailable. Technologies already in the model are still shown.": "OpenTech·DB offline — Katalog nicht verfügbar. Technologien, die bereits im Modell sind, werden weiterhin angezeigt.",
 "Opening TEMPO…": "TEMPO wird geöffnet…",
