 "Optional optimisation engine (Advanced Optimization Tool for Energy Networks) in its own isolated Python environment. Requires Python 3.10+.": "Optionale Optimierungs-Engine (Advanced Optimization Tool for Energy Networks) in einer eigenen, isolierten Python-Umgebung. Erfordert Python 3.10+.",
 "Optional optimisation engine (otoole + GLPK) in its own isolated Python environment. Requires Python 3.10+; the GLPK solver is bundled on Windows.": "Optionale Optimierungs-Engine (otoole + GLPK) in einer eigenen, isolierten Python-Umgebung. Erfordert Python 3.10+; der GLPK-Solver ist unter Windows enthalten.",
 "Optional optimisation engine in its own isolated Python environment. Requires Python 3.10+.": "Optionale Optimierungs-Engine in einer eigenen, isolierten Python-Umgebung. Erfordert Python 3.10+.",
 "Optional second optimisation engine (Calliope 0.7.0.dev7, pre-release) in its own isolated Python environment. Any TEMPO model can run on either engine — the translation from TEMPO's internal representation happens automatically at run time. Requires Python 3.10+.": "Optionale zweite Optimierungs-Engine (Calliope 0.7.0.dev7, Vorabversion) in einer eigenen, isolierten Python-Umgebung. Jedes TEMPO-Modell kann auf beiden Engines laufen — die Übersetzung aus TEMPOs interner Darstellung erfolgt automatisch zur Laufzeit. Erfordert Python 3.10+.",
