 "Set param": "Parameter setzen",
 "Set parameter": "Parameter setzen",
 "Set the cap in your CO₂ cost units (e.g. tonnes/MWh × capacity). Adjust the default to match your model's cost-class scale.": "Legen Sie die Obergrenze in Ihren CO₂-Kosteneinheiten fest (z. B. Tonnen/MWh × Kapazität). Passen Sie den Standard an die Skala der Kostenklasse Ihres Modells an.",
 "Set up and start an optimisation of the active model.": "Eine Optimierung des aktiven Modells einrichten und starten.",
 "Sets a 100% minimum renewable share via group_constraints. Combine with battery_expansion or hydrogen_storage for reliability.": "Setzt über group_constraints einen Mindestanteil von 100 % Erneuerbaren. Für Versorgungssicherheit mit battery_expansion oder hydrogen_storage kombinieren.",
 "Sets a loose upper bound on CO₂. Useful as a policy-neutral reference to compare against stricter scenarios.": "Setzt eine lockere Obergrenze für CO₂. Nützlich als politisch neutrale Referenz zum Vergleich mit strengeren Szenarien.",
 "Sets coal energy_cap_max = 0. Use alongside a CO₂ cap to also restrict gas-fired generation. Compare with the baseline to see cost and reliability impacts.": "Setzt bei Kohle energy_cap_max = 0. Zusammen mit einer CO₂-Obergrenze verwenden, um auch die Gaserzeugung einzuschränken. Mit dem Basisfall vergleichen, um Kosten- und Zuverlässigkeitsfolgen zu sehen.",
 "Sets force_resource: true on the demand technology. The model cannot curtail demand. Combine with ensure_feasibility to avoid infeasibility.": "Setzt force_resource: true bei der Nachfragetechnologie. Das Modell kann die Nachfrage nicht abregeln. Mit ensure_feasibility kombinieren, um Unlösbarkeit zu vermeiden.",
 "Settings": "Einstellungen",
 "Settings → Clear All Data": "Einstellungen → Alle Daten löschen",
 "Setup TEMPO": "TEMPO einrichten",
 "Shadow Prices": "Schattenpreise",
 "Shadow prices are the dual variables of the system energy balance constraints — they represent the marginal cost of supplying one additional unit of energy at each node and timestep. Only available for Calliope 0.7 (HiGHS solver).": "Schattenpreise sind die dualen Variablen der Energiebilanz-Nebenbedingungen des Systems — sie geben die Grenzkosten an, um an jedem Knoten und Zeitschritt eine zusätzliche Energieeinheit bereitzustellen. Nur für Calliope 0.7 (HiGHS-Solver) verfügbar.",
