 "Switch mode to \"Link\", then click two locations to create a transmission line. Set voltage (kV) and capacity (MW) in the dialog.": "Wechseln Sie in den Modus „Verbindung“ und klicken Sie zwei Standorte an, um eine Übertragungsleitung zu erstellen. Spannung (kV) und Kapazität (MW) im Dialog festlegen.",
