 "TEMPO (Tool for Energy Model Planning and Optimisation) stores your energy system models": "TEMPO (Tool for Energy Model Planning and Optimisation) speichert Ihre Energiesystemmodelle",
 "TEMPO Model Dashboard": "TEMPO-Modell-Dashboard",
 "TEMPO auto-detects the Calliope version (0.6 vs 0.7), applies the parameter mapping, and opens the": "TEMPO erkennt die Calliope-Version (0.6 oder 0.7) automatisch, wendet die Parameterzuordnung an und öffnet die",
 "TEMPO can overlay real power infrastructure from OpenStreetMap — power lines, substations, and plants — to help you ground your model in physical reality.": "TEMPO kann reale Strominfrastruktur aus OpenStreetMap einblenden — Stromleitungen, Umspannwerke und Kraftwerke —, damit Ihr Modell auf der physischen Realität aufbaut.",
 "TEMPO helps you build an energy system model, optimise it with an open-source engine and explore the results. This short tour shows where everything lives.": "Mit TEMPO bauen Sie ein Energiesystemmodell, optimieren es mit einer Open-Source-Engine und erkunden die Ergebnisse. Diese kurze Tour zeigt, wo alles zu finden ist.",
 "TEMPO is up to date": "TEMPO ist auf dem neuesten Stand",
 "TEMPO logo": "TEMPO-Logo",
 "TEMPO meshes the OpenStreetMap power lines into grid nodes + links (unchanged).": "TEMPO vernetzt die OpenStreetMap-Stromleitungen zu Netzknoten + Verbindungen (unverändert).",
 "TEMPO saves automatically. Switch to": "TEMPO speichert automatisch. Wechseln Sie zu",
 "TEMPO stores all model data locally on this device. To look for updates it contacts GitHub (api.github.com) and sends no model data; turn this off under General.": "TEMPO speichert alle Modelldaten lokal auf diesem Gerät. Zur Suche nach Updates kontaktiert es GitHub (api.github.com) und sendet keine Modelldaten; dies lässt sich unter „Allgemein“ abschalten.",
 "TEMPO version": "TEMPO-Version",
