 "Test mode: the download is verified. Nothing will be installed; the file will be shown in its folder.": "Testmodus: Der Download ist geprüft. Es wird nichts installiert; die Datei wird in ihrem Ordner angezeigt.",
 "Test robustness: all capital costs +20% from baseline.": "Robustheit testen: alle Kapitalkosten +20 % gegenüber dem Basisfall.",
 "Test sensitivity to future solar cost reductions.": "Sensitivität gegenüber künftig sinkenden Solarkosten testen.",
 "Test system adequacy with 20% higher electricity demand.": "Versorgungssicherheit bei 20 % höherer Stromnachfrage testen.",
 "Testing…": "Teste…",
 "Tests the hardest reliability period for most European grids. High heating demand with short days and low PV output.": "Prüft den schwierigsten Zuverlässigkeitszeitraum der meisten europäischen Netze. Hoher Heizbedarf bei kurzen Tagen und geringer PV-Erzeugung.",
 "The API catalog will load automatically.": "Der API-Katalog wird automatisch geladen.",
 "The CSV structure TEMPO expects, with downloadable examples.": "Die von TEMPO erwartete CSV-Struktur, mit herunterladbaren Beispielen.",
 "The Calliope 0.7 engine is not running. Install it from Settings → Calliope 0.7 Engine.": "Die Calliope-0.7-Engine läuft nicht. Installieren Sie sie unter Einstellungen → Calliope-0.7-Engine.",
 "The Calliope default. Minimises the sum of capital + operating costs across all technologies and locations.": "Der Calliope-Standard. Minimiert die Summe aus Kapital- und Betriebskosten über alle Technologien und Standorte.",
 "The OSM Infrastructure Panel (Right Sidebar)": "Der Bereich „OSM-Infrastruktur“ (rechte Seitenleiste)",
 "The OSeMOSYS engine is not running. Install it from Settings → OSeMOSYS Engine.": "Die OSeMOSYS-Engine läuft nicht. Installieren Sie sie unter Einstellungen → OSeMOSYS-Engine.",
 "The PyPSA engine is not running. Install it from Settings → PyPSA Engine.": "Die PyPSA-Engine läuft nicht. Installieren Sie sie unter Einstellungen → PyPSA-Engine.",
 "The coloured lines on the map are a live preview of the wiring you chose — nothing is added to the model until you press Import.": "Die farbigen Linien auf der Karte sind eine Live-Vorschau der gewählten Verschaltung — dem Modell wird nichts hinzugefügt, bis Sie auf „Importieren“ klicken.",
 "The connection and its transmission settings will be removed.": "Die Verbindung und ihre Übertragungseinstellungen werden entfernt.",
 "The default Calliope mode. The model chooses how much capacity to build at each location to minimise total system cost.": "Der Standardmodus von Calliope. Das Modell entscheidet, wie viel Kapazität an jedem Standort gebaut wird, um die Systemkosten zu minimieren.",
 "The exported files will be permanently removed.": "Die exportierten Dateien werden dauerhaft entfernt.",
 "The framework the archive is written for.": "Das Framework, für das das Archiv geschrieben ist.",
 "The interface at a glance": "Die Oberfläche auf einen Blick",
 "The map": "Die Karte",
 "The model to run and the mode, e.g. Plan (optimise capacities) or Operate (dispatch only).": "Das auszuführende Modell und der Modus, z. B. „Planen“ (Kapazitäten optimieren) oder „Betreiben“ (nur Einsatz).",
 "The modelling framework the model is translated to.": "Das Modellierungsframework, in das das Modell übersetzt wird.",
 "The period the model is optimised over.": "Der Zeitraum, über den das Modell optimiert wird.",
 "The run and its results will be removed from TEMPO. The model itself is not affected.": "Der Lauf und seine Ergebnisse werden aus TEMPO entfernt. Das Modell selbst ist nicht betroffen.",
 "The run completed in SPORES mode, but the per-SPORE breakdown was not extracted. This usually means the backend encountered an error during SPORES result processing.": "Der Lauf wurde im SPORES-Modus abgeschlossen, aber die Aufschlüsselung pro SPORE wurde nicht extrahiert. Meist ist dem Backend bei der Verarbeitung der SPORES-Ergebnisse ein Fehler unterlaufen.",
 "The saved model on a map. Edit locations and links directly here.": "Das gespeicherte Modell auf einer Karte. Standorte und Verbindungen hier direkt bearbeiten.",
