 "Upload": "Hochladen",
 "Upload CSV": "CSV hochladen",
 "Upload CSV files containing your Calliope model data or load example data": "CSV-Dateien mit Ihren Calliope-Modelldaten hochladen oder Beispieldaten laden",
 "Upload Calliope Model Data": "Calliope-Modelldaten hochladen",
 "Upload Files": "Dateien hochladen",
 "Upload a CSV with hourly demand or resource data. Here is the format TEMPO expects.": "Laden Sie eine CSV mit stündlichen Nachfrage- oder Ressourcendaten hoch. So sieht das von TEMPO erwartete Format aus.",
 "Upload and manage CSV demand & resource capacity-factor profiles": "CSV-Profile für Nachfrage & Ressourcen-Kapazitätsfaktoren hochladen und verwalten",
 "Upload hourly demand and resource profiles (CSV).": "Stündliche Nachfrage- und Ressourcenprofile hochladen (CSV).",
 "Upload multiple CSV files with hourly data (demand, solar, wind, prices, etc.)": "Mehrere CSV-Dateien mit Stundenwerten hochladen (Nachfrage, Solar, Wind, Preise usw.)",
 "Upload the two required files that define your model topology.": "Laden Sie die zwei erforderlichen Dateien hoch, die die Topologie Ihres Modells festlegen.",
 "Upload via Import": "Über den Import hochladen",
 "Uploaded files with their columns. Select one to chart it, download it or delete it.": "Hochgeladene Dateien mit ihren Spalten. Wählen Sie eine aus, um sie darzustellen, herunterzuladen oder zu löschen.",
 "Uploading to PostGIS (calliope-postgis:5432)…": "Wird in PostGIS hochgeladen (calliope-postgis:5432)…",
 "Use after a planning run. Capacities are fixed and only dispatch decisions are optimised. Useful for profiling system operation.": "Nach einem Planungslauf verwenden. Kapazitäten sind fest, nur Einsatzentscheidungen werden optimiert. Nützlich, um den Systembetrieb zu analysieren.",
 "Use multiple CPU threads to speed up solving.": "Mehrere CPU-Threads nutzen, um das Lösen zu beschleunigen.",
 "Use once the model is validated. The optimisation will fail if supply cannot meet demand, which highlights structural issues.": "Verwenden, sobald das Modell geprüft ist. Die Optimierung schlägt fehl, wenn das Angebot die Nachfrage nicht decken kann — so werden strukturelle Probleme sichtbar.",
 "Use the Power Mesh Generator to automatically extract a network topology from OSM data.": "Nutzen Sie den Stromnetz-Generator, um automatisch eine Netztopologie aus OSM-Daten zu extrahieren.",
 "Use this to quickly verify that the model structure is correct before committing to a full solve. Sets time range to the first 24 h of your timeseries.": "Damit lässt sich schnell prüfen, ob die Modellstruktur stimmt, bevor eine vollständige Lösung gerechnet wird. Setzt den Zeitraum auf die ersten 24 Stunden Ihrer Zeitreihe.",
 "Use when frequency regulation or intra-hour ramps are important. Maximises accuracy but increases solve time.": "Verwenden, wenn Frequenzregelung oder untertägige Rampen wichtig sind. Maximale Genauigkeit, aber längere Lösungszeit.",
 "Uses a Calliope group_constraints cost_max on the co2 cost class. Requires technologies to have co2 costs defined.": "Verwendet in Calliope ein group_constraints cost_max auf die Kostenklasse co2. Erfordert für die Technologien definierte co2-Kosten.",
 "Uses a group_constraints carrier_prod_min_systemwide constraint. List your renewable technology names in the techs field.": "Verwendet eine Nebenbedingung group_constraints carrier_prod_min_systemwide. Listen Sie die Namen Ihrer erneuerbaren Technologien im Feld techs auf.",
 "Uses resource_scale to uniformly multiply the demand timeseries. For example 1.2 represents +20% growth. Applies to the named demand technology.": "Verwendet resource_scale, um die Nachfrage-Zeitreihe gleichmäßig zu multiplizieren. 1,2 entspricht z. B. +20 % Wachstum. Gilt für die genannte Nachfragetechnologie.",
 "Using a synthetic approximation. Install BDEW load profiles (demandlib) for real curves.": "Es wird eine synthetische Näherung verwendet. Installieren Sie die BDEW-Lastprofile (demandlib) für reale Kurven.",
 "Using this feature sends your selected run's results to your chosen LLM provider (": "Diese Funktion sendet die Ergebnisse des gewählten Laufs an Ihren gewählten KI-Anbieter (",
 "Utilisation of capacity expansion potential (Fig 2)": "Ausschöpfung des Kapazitätsausbaupotenzials (Abb. 2)",
