 "Fixed O&M cost": "Fixe Betriebs- & Wartungskosten",
 "Variable O&M cost": "Variable Betriebs- & Wartungskosten",
 "Interest rate": "Zinssatz",
 "Maximum storage capacity": "Maximale Speicherkapazität",
 "Storage capital cost (per energy)": "Speicher-Investitionskosten (pro Energie)",
 "Storage standing loss": "Speicher-Selbstentladung",
 "C-rate (power/energy)": "C-Rate (Leistung/Energie)",
 "fraction": "Anteil",
